import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.List;

public class Main {

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String s = reader.readLine().trim();
        int n = s.length();

        final int INF = 1_000_000;

        // dp[i][k] = shortest length to parse prefix of length i with k '@' placed so far
        int[][] dp = new int[n + 1][3];
        // parent[i][k] = previous state (prev_i, prev_k, action)
        // action: 0 = letter, 1 = dot, 2 = at
        State[][] parent = new State[n + 1][3];

        for (int i = 0; i <= n; i++) {
            Arrays.fill(dp[i], INF);
        }
        dp[0][0] = 0;

        for (int i = 0; i <= n; i++) {
            for (int k = 0; k <= 2; k++) {
                if (dp[i][k] == INF) continue;

                // 1. Take a single letter
                if (i < n) {
                    char c = s.charAt(i);
                    if (c >= 'a' && c <= 'z') {
                        int ni = i + 1;
                        int nk = k;
                        int nlen = dp[i][k] + 1;
                        if (nlen < dp[ni][nk] || (nlen == dp[ni][nk] && isBetter(ni, nk, i, k, 0, c, dp, parent, s))) {
                            dp[ni][nk] = nlen;
                            parent[ni][nk] = new State(i, k, 0, c);
                        }
                    }
                }

                // 2. Replace "dot" with '.'
                if (i + 3 <= n && s.substring(i, i + 3).equals("dot")) {
                    int ni = i + 3;
                    int nk = k;
                    int nlen = dp[i][k] + 1;
                    if (nlen < dp[ni][nk] || (nlen == dp[ni][nk] && isBetter(ni, nk, i, k, 1, '.', dp, parent, s))) {
                        dp[ni][nk] = nlen;
                        parent[ni][nk] = new State(i, k, 1, '.');
                    }
                }

                // 3. Replace "at" with '@'
                if (i + 2 <= n && s.substring(i, i + 2).equals("at")) {
                    if (k == 0) {
                        int ni = i + 2;
                        int nk = 1;
                        int nlen = dp[i][k] + 1;
                        if (nlen < dp[ni][nk] || (nlen == dp[ni][nk] && isBetter(ni, nk, i, k, 2, '@', dp, parent, s))) {
                            dp[ni][nk] = nlen;
                            parent[ni][nk] = new State(i, k, 2, '@');
                        }
                    }
                }
            }
        }

        // We need exactly one '@', so k=1 at the end
        if (dp[n][1] == INF) {
            // Should not happen based on problem constraints
            return;
        }

        // Reconstruct the email
        StringBuilder result = new StringBuilder();
        int curI = n;
        int curK = 1;
        while (curI > 0 || curK > 0) {
            State st = parent[curI][curK];
            if (st == null) break;
            result.append(st.ch);
            curI = st.prevI;
            curK = st.prevK;
        }
        result.reverse();

        // Verify constraints just in case (start/end with . or @)
        // The DP should handle it if we check transitions, but problem says input is valid description.
        // Lexicographical order: . < @ < a...z
        // Our DP tie-breaking logic handles this.

        System.out.println(result.toString());
    }

    // Compares two candidate paths leading to the same state (i, k).
    // Returns true if the path via (pi, pk) with action 'action' and char 'ch' is lexicographically smaller
    // than the current path stored in parent[i][k].
    // Lexicographical order: . < @ < a...z
    // We need to compare the resulting strings.
    // Since we build forward, we compare the string built so far.
    // We can compare by reconstructing the strings for the two paths.
    // Given length <= 100, reconstructing strings for comparison is acceptable.
    private static boolean isBetter(int i, int k, int pi, int pk, int action, char ch, int[][] dp, State[][] parent, String s) {
        // Build string for new candidate
        StringBuilder cand = new StringBuilder();
        cand.append(ch);
        int ci = pi, ck = pk;
        while (ci > 0 || ck > 0) {
            State st = parent[ci][ck];
            if (st == null) break;
            cand.append(st.ch);
            ci = st.prevI;
            ck = st.prevK;
        }
        cand.reverse();

        // Build string for current best
        StringBuilder curr = new StringBuilder();
        State stCurr = parent[i][k];
        if (stCurr != null) {
            // Note: parent[i][k] currently stores the *previous* state for the current best path.
            // We need to reconstruct the full string for the current best path.
            // However, parent[i][k] might be the state we are trying to update.
            // Actually, parent[i][k] stores the predecessor of the current best path.
            // So we reconstruct from parent[i][k].
            int ci2 = i, ck2 = k;
            // The current best string ends at (i,k). Its last char is parent[i][k].ch
            // Wait, parent stores the transition *to* this state.
            // So parent[i][k] contains the char added to reach (i,k).
            // So we can reconstruct the current best string by following parent links from (i,k).
            while (ci2 > 0 || ck2 > 0) {
                State st = parent[ci2][ck2];
                if (st == null) break;
                curr.append(st.ch);
                ci2 = st.prevI;
                ck2 = st.prevK;
            }
            curr.reverse();
        } else {
            // No current best, new one is better
            return true;
        }

        // Compare lengths (should be equal here)
        if (cand.length() != curr.length()) {
            return cand.length() < curr.length();
        }
        return cand.toString().compareTo(curr.toString()) < 0;
    }

    static class State {
        int prevI;
        int prevK;
        int action; // 0: letter, 1: dot, 2: at
        char ch;    // resulting character

        State(int prevI, int prevK, int action, char ch) {
            this.prevI = prevI;
            this.prevK = prevK;
            this.action = action;
            this.ch = ch;
        }
    }
}
